//! The Snowball English stemmer as PostgreSQL 19 builds it: a port of
//! `src/backend/snowball/libstemmer/stem_UTF_8_english.c` (generated by
//! Snowball 3.0.0) and the parts of `utilities.c` and `api.c` it calls,
//! run the way `dict_snowball.c` runs it. Cursors count bytes of UTF-8, as
//! the C's do.

/// Stems one word the way PostgreSQL's `english` Snowball dictionary does
/// between lower-casing and its stop-word check: `SN_set_current`, then
/// `english_UTF_8_stem`, then `dsnowball_lexize`'s copy of the result,
/// which keeps the word as given when the stem comes out empty.
///
/// The caller keeps `dsnowball_lexize`'s other steps: lower-casing, the
/// empty word and stop words reported as stop words, and a word longer than
/// 1000 bytes before lower-casing returned lower-cased without stemming.
pub(crate) fn english_stem(word: &str) -> String {
    let mut z = Env::new(word.as_bytes());
    // A negative result is the C's slice error; dsnowball_lexize ignores
    // it and copies out whatever the buffer holds.
    let _ = z.english_utf_8_stem();
    if z.l == 0 {
        return word.to_string();
    }
    String::from_utf8(z.p).unwrap_or_else(|e| String::from_utf8_lossy(e.as_bytes()).into_owned())
}

/// One entry of a Snowball `among` table (`struct among`); none of the
/// English tables carries a condition routine, so that field is left out.
struct Among {
    s: &'static [u8],
    substring_i: i32,
    result: i32,
}

const fn am(s: &'static [u8], substring_i: i32, result: i32) -> Among {
    Among {
        s,
        substring_i,
        result,
    }
}

