#[cfg(test)]
mod tests {
    use super::english_stem;

    /// Each pair is a word and the stem PostgreSQL 19 RC1's
    /// `ts_lexize` gives it under a Snowball `english` dictionary without
    /// stop words.
    const CASES: &[(&str, &str)] = &[
        // r_prelude: a leading apostrophe, a leading y, a y after a vowel.
        ("'tis", "tis"),
        ("yearly", "year"),
        ("sayings", "say"),
        // r_mark_regions: a prefix of a_0 ends R1.
        ("arsenal", "arsenal"),
        // r_Step_1a.
        ("caresses", "caress"),
        ("ponies", "poni"),
        ("ties", "tie"),
        ("kiwis", "kiwi"),
        ("dog's", "dog"),
        // Every byte deleted: dsnowball_lexize keeps the word.
        ("''s", "''s"),
        // r_Step_1b, with r_shortv and the a_3, a_4 and a_6 tables.
        ("agreed", "agre"),
        ("proceed", "proceed"),
        ("hopping", "hop"),
        ("hoping", "hope"),
        ("dying", "die"),
        ("inning", "inning"),
        // r_Step_1c.
        ("cry", "cri"),
        // r_Step_2, r_Step_3, r_Step_4, r_Step_5.
        ("relational", "relat"),
        ("electrical", "electr"),
        ("formative", "format"),
        ("adjustment", "adjust"),
        ("adoption", "adopt"),
        ("controll", "control"),
        // r_exception1.
        ("skies", "sky"),
        ("gently", "gentl"),
        ("news", "news"),
        // Characters past ASCII, counted in bytes as the C counts them.
        ("cafés", "café"),
        ("naïvely", "naïv"),
        ("😀ing", "😀ing"),
        ("ééied", "ééi"),
    ];

    #[test]
    fn matches_postgresql() {
        for (word, stem) in CASES {
            assert_eq!(english_stem(word), *stem, "word {word:?}");
        }
    }
}
